<?php
namespace App\Http\Controllers\Api\Hr;use App\Http\Controllers\Controller;use App\Models\Staff;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class HrNotificationController extends Controller{
public function templates(Request$r):JsonResponse{$a=$this->actor($r);return response()->json(['status'=>'success','data'=>DB::table('hr_notification_template_versions')->where('company_id',$a->company_id)->select(['id','code','version','event_type','channel','allowed_placeholders','mandatory','effective_from','effective_until','status','template_checksum'])->orderBy('code')->orderByDesc('version')->paginate($r->integer('per_page',50))]);}
public function storeTemplate(Request$r):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['code'=>['required','string','max:100'],'version'=>['required','integer','min:1'],'event_type'=>['required','string','max:100'],'channel'=>['required',Rule::in(['in_app','email','sms'])],'subject_template'=>['nullable','required_if:channel,email','string','max:500'],'body_template'=>['required','string','max:20000'],'allowed_placeholders'=>['required','array'],'allowed_placeholders.*'=>['required','string','regex:/^[a-zA-Z0-9_.-]+$/','distinct'],'mandatory'=>['required','boolean'],'effective_from'=>['required','date'],'effective_until'=>['nullable','date','after_or_equal:effective_from']]);preg_match_all('/\{\{\s*([a-zA-Z0-9_.-]+)\s*\}\}/',($d['subject_template']??'').' '.$d['body_template'],$matches);abort_if(array_diff(array_unique($matches[1]),$d['allowed_placeholders']),422,'Every template placeholder must be explicitly allowed.');$checksum=hash('sha256',json_encode($d,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$id=(string)Str::uuid();$d['allowed_placeholders']=json_encode(array_values($d['allowed_placeholders']),JSON_THROW_ON_ERROR);DB::table('hr_notification_template_versions')->insert($d+['id'=>$id,'company_id'=>$a->company_id,'status'=>'pending_approval','template_checksum'=>$checksum,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_notification_template_versions')->find($id)],201);}
public function approveTemplate(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);return DB::transaction(function()use($r,$a,$id){$t=DB::table('hr_notification_template_versions')->where('id',$id)->where('company_id',$a->company_id)->lockForUpdate()->first();abort_unless($t,404);abort_unless($t->status==='pending_approval',409);abort_if($t->created_by===$r->user()->id,409,'Template creator cannot approve the same version.');$overlap=DB::table('hr_notification_template_versions')->where('company_id',$a->company_id)->where('event_type',$t->event_type)->where('channel',$t->channel)->where('status','approved')->whereDate('effective_from','<=',$t->effective_until??'9999-12-31')->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',$t->effective_from))->exists();abort_if($overlap,409,'Approved notification templates cannot overlap for an event and channel.');DB::table('hr_notification_template_versions')->where('id',$id)->update(['status'=>'approved','approved_by'=>$r->user()->id,'approved_at'=>now(),'updated_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_notification_template_versions')->find($id)]);});}
public function rejectTemplate(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['reason'=>['required','string','max:3000']]);return DB::transaction(function()use($r,$a,$d,$id){$t=DB::table('hr_notification_template_versions')->where('id',$id)->where('company_id',$a->company_id)->lockForUpdate()->first();abort_unless($t,404);abort_unless($t->status==='pending_approval',409);abort_if($t->created_by===$r->user()->id,409,'Template creator cannot reject the same version.');DB::table('hr_notification_template_versions')->where('id',$id)->update(['status'=>'rejected','approved_by'=>$r->user()->id,'approved_at'=>now(),'decision_reason'=>$d['reason'],'updated_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_notification_template_versions')->find($id)]);});}
public function preferences(Request$r):JsonResponse{$a=$this->actor($r);return response()->json(['status'=>'success','data'=>DB::table('hr_notification_preferences')->where('staff_id',$a->id)->select(['event_type','channel','enabled','updated_at'])->get()]);}
public function savePreference(Request$r):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['event_type'=>['required','string','max:100'],'channel'=>['required',Rule::in(['in_app','email','sms'])],'enabled'=>['required','boolean']]);if(!$d['enabled'])abort_if(DB::table('hr_notification_template_versions')->where('company_id',$a->company_id)->where('event_type',$d['event_type'])->where('channel',$d['channel'])->where('status','approved')->where('mandatory',true)->whereDate('effective_from','<=',now())->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',now()))->exists(),422,'Mandatory HR notifications cannot be disabled.');$key=['staff_id'=>$a->id,'event_type'=>$d['event_type'],'channel'=>$d['channel']];DB::table('hr_notification_preferences')->insertOrIgnore($key+['id'=>(string)Str::uuid(),'company_id'=>$a->company_id,'enabled'=>$d['enabled'],'updated_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('hr_notification_preferences')->where($key)->update(['enabled'=>$d['enabled'],'updated_by'=>$r->user()->id,'updated_at'=>now()]);return response()->json(['status'=>'success']);}
public function outbox(Request$r):JsonResponse{$a=$this->actor($r);return response()->json(['status'=>'success','data'=>DB::table('hr_notification_outbox')->where('company_id',$a->company_id)->select(['id','template_version_id','recipient_staff_id','event_type','channel','source_type','source_id','payload_checksum','status','attempt_count','available_at','accepted_at','delivered_at','external_reference','last_error'])->latest()->paginate($r->integer('per_page',50))]);}
public function deliveryQueue(Request$r):JsonResponse{$this->enabled();$a=$this->actor($r);$max=max(1,(int)config('hr.notification_max_attempts',5));$rows=DB::table('hr_notification_outbox')->where('company_id',$a->company_id)->where('attempt_count','<',$max)->where(function($q){$q->where(function($ready){$ready->whereIn('status',['pending_delivery','retryable'])->where('available_at','<=',now());})->orWhere(function($expired){$expired->where('status','delivering')->whereNotNull('leased_until')->where('leased_until','<=',now());});})->select(['id','channel','event_type','payload_checksum','status','attempt_count','available_at','leased_until'])->orderBy('available_at')->paginate(min(100,max(1,$r->integer('per_page',50))));return response()->json(['status'=>'success','data'=>$rows]);}
public function receiptQueue(Request$r):JsonResponse{$this->enabled();$a=$this->actor($r);$rows=DB::table('hr_notification_outbox')->where('company_id',$a->company_id)->where('status','accepted_pending_receipt')->select(['id','channel','event_type','payload_checksum','attempt_count','accepted_at','external_reference'])->orderBy('accepted_at')->paginate(min(100,max(1,$r->integer('per_page',50))));return response()->json(['status'=>'success','data'=>$rows]);}
public function claimDelivery(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);return DB::transaction(function()use($r,$a,$id){$o=DB::table('hr_notification_outbox')->where('id',$id)->where('company_id',$a->company_id)->lockForUpdate()->first();abort_unless($o,404);$claimable=in_array($o->status,['pending_delivery','retryable'],true)&&now()->greaterThanOrEqualTo($o->available_at);$expired=$o->status==='delivering'&&$o->leased_until&&now()->greaterThanOrEqualTo($o->leased_until);abort_unless($claimable||$expired,409,'Notification is not available for delivery.');$max=max(1,(int)config('hr.notification_max_attempts',5));if($o->attempt_count>=$max){DB::table('hr_notification_outbox')->where('id',$id)->update(['status'=>'failed','lease_token'=>null,'leased_until'=>null,'last_error'=>'Notification delivery lease expired at the configured attempt limit.','updated_at'=>now()]);DB::table('hr_notification_delivery_events')->insertOrIgnore(['id'=>(string)Str::uuid(),'outbox_id'=>$id,'event_type'=>'failed','attempt_number'=>$o->attempt_count,'payload_checksum'=>$o->payload_checksum,'message'=>'Notification delivery lease expired at the configured attempt limit.','actor_user_id'=>$r->user()->id,'occurred_at'=>now()]);return response()->json(['status'=>'error','message'=>'Notification delivery attempt limit has been reached.'],409);}$attempt=$o->attempt_count+1;$leaseToken=hash('sha256',Str::random(64).$o->id.now()->format('U.u'));$leasedUntil=now()->addSeconds(max(30,(int)config('hr.notification_lease_seconds',120)));DB::table('hr_notification_outbox')->where('id',$id)->update(['status'=>'delivering','attempt_count'=>$attempt,'lease_token'=>$leaseToken,'leased_until'=>$leasedUntil,'updated_at'=>now()]);DB::table('hr_notification_delivery_events')->insert(['id'=>(string)Str::uuid(),'outbox_id'=>$id,'event_type'=>$expired?'reclaimed':'claimed','attempt_number'=>$attempt,'payload_checksum'=>$o->payload_checksum,'message'=>$expired?'Expired adapter lease was reclaimed.':null,'actor_user_id'=>$r->user()->id,'occurred_at'=>now()]);return response()->json(['status'=>'success','data'=>['id'=>$o->id,'channel'=>$o->channel,'recipient_user_id'=>$o->recipient_user_id,'event_type'=>$o->event_type,'payload'=>decrypt($o->encrypted_rendered_payload),'payload_checksum'=>$o->payload_checksum,'attempt_count'=>$attempt,'lease_token'=>$leaseToken,'leased_until'=>$leasedUntil]]);});}
public function acknowledge(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['outcome'=>['required',Rule::in(['accepted','failed'])],'payload_checksum'=>['required','string','size:64'],'lease_token'=>['required','string','size:64'],'external_reference'=>['nullable','required_if:outcome,accepted','string','max:160'],'message'=>['required_if:outcome,failed','string','max:4000']]);return DB::transaction(function()use($r,$a,$id,$d){$o=DB::table('hr_notification_outbox')->where('id',$id)->where('company_id',$a->company_id)->lockForUpdate()->first();abort_unless($o,404);abort_unless($o->status==='delivering'&&$o->leased_until&&now()->lessThan($o->leased_until),409,'Notification delivery lease is not active.');abort_unless(hash_equals((string)$o->lease_token,$d['lease_token']),409,'Notification delivery lease mismatch.');abort_unless(hash_equals($o->payload_checksum,$d['payload_checksum']),409,'Notification payload checksum mismatch.');$accepted=$d['outcome']==='accepted';$max=max(1,(int)config('hr.notification_max_attempts',5));$terminal=!$accepted&&$o->attempt_count>=$max;$status=$accepted?'accepted_pending_receipt':($terminal?'failed':'retryable');$delay=min(max(1,(int)config('hr.notification_retry_max_minutes',60)),2**max(0,$o->attempt_count-1));DB::table('hr_notification_outbox')->where('id',$id)->update(['status'=>$status,'available_at'=>$accepted||$terminal?$o->available_at:now()->addMinutes($delay),'lease_token'=>null,'leased_until'=>null,'accepted_at'=>$accepted?now():null,'external_reference'=>$d['external_reference']??null,'last_error'=>$accepted?null:($d['message']??'Adapter handoff failed.'),'updated_at'=>now()]);DB::table('hr_notification_delivery_events')->insert(['id'=>(string)Str::uuid(),'outbox_id'=>$id,'event_type'=>$accepted?'provider_accepted':($terminal?'failed':'retry_scheduled'),'attempt_number'=>$o->attempt_count,'payload_checksum'=>$o->payload_checksum,'external_reference'=>$d['external_reference']??null,'message'=>$d['message']??null,'actor_user_id'=>$r->user()->id,'occurred_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_notification_outbox')->find($id)]);});}
public function recordReceipt(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['outcome'=>['required',Rule::in(['delivered','failed'])],'payload_checksum'=>['required','string','size:64'],'external_reference'=>['required','string','max:160'],'provider_event_id'=>['required','string','max:200'],'message'=>['nullable','required_if:outcome,failed','string','max:4000']]);return DB::transaction(function()use($r,$a,$id,$d){$prior=DB::table('hr_notification_delivery_events')->where('provider_event_id',$d['provider_event_id'])->first();if($prior){abort_unless($prior->outbox_id===$id&&$prior->event_type===$d['outcome'],409,'Provider receipt identifier was already used for a different delivery fact.');return response()->json(['status'=>'success','data'=>DB::table('hr_notification_outbox')->where('id',$id)->where('company_id',$a->company_id)->first()]);}$o=DB::table('hr_notification_outbox')->where('id',$id)->where('company_id',$a->company_id)->lockForUpdate()->first();abort_unless($o,404);abort_unless($o->status==='accepted_pending_receipt',409,'Notification is not awaiting a provider receipt.');abort_unless(hash_equals($o->payload_checksum,$d['payload_checksum']),409,'Notification payload checksum mismatch.');abort_unless(hash_equals((string)$o->external_reference,$d['external_reference']),409,'Provider reference does not match the accepted handoff.');$delivered=$d['outcome']==='delivered';DB::table('hr_notification_outbox')->where('id',$id)->update(['status'=>$d['outcome'],'delivered_at'=>$delivered?now():null,'last_error'=>$delivered?null:($d['message']??'Provider reported delivery failure.'),'updated_at'=>now()]);DB::table('hr_notification_delivery_events')->insert(['id'=>(string)Str::uuid(),'outbox_id'=>$id,'event_type'=>$d['outcome'],'attempt_number'=>$o->attempt_count,'payload_checksum'=>$o->payload_checksum,'external_reference'=>$o->external_reference,'provider_event_id'=>$d['provider_event_id'],'message'=>$d['message']??null,'actor_user_id'=>$r->user()->id,'occurred_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_notification_outbox')->find($id)]);});}
private function actor(Request$r):Staff{return Staff::query()->where('user_id',$r->user()->id)->firstOrFail();}private function enabled():void{abort_unless(config('hr.features.engagement_analytics',false),409,'HR engagement and analytics writes are not enabled.');}}
